import React, { useState, useEffect } from 'react';
import axios from 'axios';
import { useParams } from 'react-router-dom';

const CreateProjeto = () => {
  const [nome, setNome] = useState('');
  const [status, setStatus] = useState('');
  const [statusOptions, setStatusOptions] = useState([]);
  const [clientes, setClientes] = useState([]);
  const [clienteId, setClienteId] = useState('');
  const [dataInicio, setDataInicio] = useState('');
  const [dataTermino, setDataTermino] = useState('');

  // Função para pegar os status do backend
  useEffect(() => {
    const fetchStatusOptions = async () => {
      try {
        const response = await axios.get('http://localhost:8080/api/status-projeto'); // URL que retorna os status
        setStatusOptions(response.data); // A resposta será uma lista de status
      } catch (error) {
        console.error('Erro ao carregar os status', error);
        alert('Erro ao carregar os status do projeto!');
      }
    };

    fetchStatusOptions();
  }, []); // O useEffect será chamado apenas uma vez quando o componente for montado

  // Função para pegar os clientes
  useEffect(() => {
    const fetchClientes = async () => {
      try {
        const response = await axios.get('http://localhost:8080/api/clientes'); // URL que retorna os clientes
        setClientes(response.data); // A resposta será uma lista de clientes
      } catch (error) {
        console.error('Erro ao carregar os clientes', error);
        alert('Erro ao carregar os clientes!');
      }
    };

    fetchClientes();
  }, []); // O useEffect será chamado apenas uma vez quando o componente for montado

  // Função que lida com a criação do projeto
  const handleCreateProjeto = async (e) => {
    e.preventDefault();

    try {
      const projeto = {
        nome,
        status,
        clienteId,
        dataInicio,
        dataTermino
      };

      // Faz a requisição para criar o projeto
      await axios.post(`http://localhost:8080/clientes/${clienteId}/projetos`, projeto); // URL com clienteId
      alert('Projeto criado com sucesso!');
      setNome(''); // Limpar o nome após criação
      setStatus(''); // Limpar o status após criação
      setClienteId(''); // Limpar o clienteId após criação
      setDataInicio(''); // Limpar data de início
      setDataTermino(''); // Limpar data de término
    } catch (error) {
      console.error('Erro ao criar projeto:', error);
      alert('Erro ao criar projeto!');
    }
  };

  return (
    <div className="create-projeto">
      <h2>Criar Novo Projeto</h2>
      <form onSubmit={handleCreateProjeto} className="form-criar-projeto">
        <div>
          <input
            type="text"
            value={nome}
            onChange={(e) => setNome(e.target.value)}
            placeholder="Nome do Projeto"
            required
          />
        </div>

        <div>
          <label htmlFor="cliente">Cliente:</label>
          <select
            id="cliente"
            value={clienteId}
            onChange={(e) => setClienteId(e.target.value)} // Atualiza o cliente selecionado
            required
          >
            <option value="">Selecione o Cliente</option>
            {clientes.map((cliente) => (
              <option key={cliente.id} value={cliente.id}>
                {cliente.nome}
              </option>
            ))}
          </select>
        </div>

        <div>
          <label htmlFor="status">Status do Projeto:</label>
          <select
            id="status"
            value={status}
            onChange={(e) => setStatus(e.target.value)} // Atualiza o status selecionado
            required
          >
            <option value="">Selecione o Status</option>
            {statusOptions.map((statusOption, index) => (
              <option key={index} value={statusOption}>
                {statusOption.replace(/_/g, ' ')} {/* Exibe o status com espaços ao invés de underscores */}
              </option>
            ))}
          </select>
        </div>

        <div>
          <label htmlFor="dataInicio">Data de Início:</label>
          <input
            type="date"
            id="dataInicio"
            value={dataInicio}
            onChange={(e) => setDataInicio(e.target.value)} // Atualiza a data de início
            required
          />
        </div>

        <div>
          <label htmlFor="dataTermino">Data de Término:</label>
          <input
            type="date"
            id="dataTermino"
            value={dataTermino}
            onChange={(e) => setDataTermino(e.target.value)} // Atualiza a data de término
            required
          />
        </div>

        <button type="submit">Criar Projeto</button>
      </form>
    </div>
  );
};

export default CreateProjeto;
